3: import java.math.BigDecimal;
4: import java.time.LocalDate;
5: import java.time.temporal.ChronoUnit;
6: 
7: /**
8:  * Library lending policy.
9:  * <ul>
10:  *   <li>A loan is due {@link MemberType#loanDays()} days after it starts; a due date that falls on a Saturday or
11:  *       Sunday moves to the following Monday.</li>
12:  *   <li>Late fee: 0.25 for every day the book is returned after its due date (returning on the due date is free),
13:  *       capped at 10.00 per loan.</li>
14:  * </ul>
15:  */
16: public final class LoanPolicy {
17:     private static final BigDecimal DAILY_FEE = new BigDecimal("0.25");
18:     private static final BigDecimal MAX_FEE = new BigDecimal("10.00");
19: 
20:     public LocalDate dueDate(LocalDate start, MemberType type) {
21:         return nextBusinessDay(start.plusDays(type.loanDays()));
22:     }
23: 
24:     LocalDate nextBusinessDay(LocalDate day) {
25:         switch (day.getDayOfWeek()) {
26:             case SATURDAY:
27:             case SUNDAY:
28:                 return day.plusDays(1);
29:             default:
30:                 return day;
31:         }
32:     }
33: 
34:     public BigDecimal lateFee(LocalDate dueOn, LocalDate returnedOn) {
35:         if (!returnedOn.isAfter(dueOn)) {
36:             return BigDecimal.ZERO.setScale(2);
37:         }
38:         long days = ChronoUnit.DAYS.between(dueOn, returnedOn) + 1;
39:         return DAILY_FEE.multiply(BigDecimal.valueOf(days)).setScale(2);
40:     }
41: }

